      { qty: 5, unitPrice: 9500, discountPercent: 10, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500 + 120000);
  assert.equal(totals.discount, 4750);
  const vat = lineVat(invoice.lines[0]) + lineVat(invoice.lines[1]);
  assert.equal(totals.vat, vat);
